 for(const p of castellationCenters){const start={bottom:0,right:Math.PI/2,top:Math.PI,left:-Math.PI/2}[p.side],end=start+Math.PI;for(const[out,d,z,list,label]of[[.37,.055,1,lands,'actual gold module land'],[.27,1,0,castellations,'actual half-hole plated barrel']]){const sh=new THREE.Shape();sh.absarc(0,0,out,start,end,false);sh.lineTo(.2*Math.cos(end),.2*Math.sin(end));sh.absarc(0,0,.2,end,start,true);sh.closePath();list.push(solid(frame,sh,d,[p.x,p.y,z],gold,'LoRaWAN-CN470 RAK3172 '+label+' '+p.n));}const horizontal=p.side==='left'||p.side==='right',sign=p.side==='left'||p.side==='bottom'?-1:1;toes.push(mesh(frame,new THREE.BoxGeometry(horizontal?.8:.7,horizontal?.7:.8,.07),metal,[p.x+(horizontal?sign*.22:0),p.y+(horizontal?0:sign*.22),.015],'LoRaWAN-CN470 actual module carrier solder toe '+p.n));}
